def transform(grid):
    h, w = len(grid), len(grid[0])
    border = grid[0][0]
    vertical = any(3 in grid[r][1:-1] for r in range(1, h - 1)) and not any(
        all(x == 3 for x in grid[r][1:-1]) for r in range(1, h - 1)
    )
    if vertical:
        red_positions = [r for r in range(h) if 2 in grid[r]]
        axis_length = h
    else:
        red_positions = [c for c in range(w) if any(grid[r][c] == 2 for r in range(h))]
        axis_length = w
    starts = [p for i, p in enumerate(red_positions)
              if i == 0 or p != red_positions[i - 1] + 1]
    period = min(b - a for a, b in zip(starts, starts[1:]))
    phase = starts[0] % period
    width = sum(1 for p in red_positions if starts[0] <= p < starts[0] + period)
    active = {(phase + i) % period for i in range(width)}
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if vertical:
                if any(grid[rr][c] == 3 for rr in range(h)):
                    out[r][c] = 3
                elif grid[r][c] == 2:
                    out[r][c] = 2
                elif r % period in active:
                    out[r][c] = border
            else:
                if 3 in grid[r]:
                    out[r][c] = 3
                elif grid[r][c] == 2:
                    out[r][c] = 2
                elif c % period in active:
                    out[r][c] = border
    return out
